  Object.assign(state,{tlScenario:'normal',tlMenu:false,tlMenuTop:80,tlDeleted:[],tlCustom:[],tlTarget:'',tlConfirm:'',tlImportTags:[]});
  const tlBase=Object.keys(tagColors).map(name=>({name,color:({amber:'#aa8b29',green:'#448f5c',teal:'#219c9c',purple:'#826acb',pink:'#c56f99',blue:'#4a92ca'})[tagColors[name]]||'#448f5c'})).concat([{name:'待使用',color:'#607D8B'},{name:'备用标签',color:'#673AB7'}]);
  function tlRows(){if(state.tlScenario==='empty')return [];return [...tlBase,...state.tlCustom].filter(t=>!state.tlDeleted.includes(t.name)).map(t=>({...t,count:dRows().filter(r=>r.tag===t.name).length}));}
  function tlMenu(){const w=Math.min(phone.clientWidth-34,qPreview.scale>1.25?224:168);return `<div class="tl-menu-layer"><button class="tl-dismiss" data-action="tl-close" aria-label="关闭标签工具"></button><div class="tl-menu-panel" role="menu" aria-label="标签工具" style="top:${state.tlMenuTop}px;width:${w}px">${[['add','plus','新增标签'],['generate','sparkles','生成默认标签'],['import','download','导入标签'],['clear','trash-2','清理未使用']].map(([key,i,label])=>btn('tl-'+key,`${icon(i)}<span>${label}</span>`,label,key==='clear'?'tl-danger-text':'','role="menuitem"')).join('')}</div></div>`;}
  function tlBody(){const rows=tlRows();return `<div class="bc-subhead"><div class="bc-heading-left">${btn('back',icon('chevron-left'),'返回')}<h2>标签管理</h2></div><div class="td-actions">${btn('tl-share',icon('share-2'),'分享标签')}${btn('tl-more',icon('ellipsis'),'更多')}</div></div><div class="tl-shell"><div class="tl-scroll">${state.tlScenario==='loading'?'<div class="tl-status">'+icon('loader-circle')+'<p>正在加载标签</p></div>':state.tlScenario==='error'?`<div class="tl-status">${icon('circle-alert')}<p>加载失败</p>${btn('tl-retry','重试','重试标签加载','bc-secondary')}</div>`:rows.length?`<div class="tl-grid">${rows.map(t=>`<section class="tl-card"><button class="tl-open" data-action="tl-open:${esc(t.name)}" aria-label="查看标签 ${esc(t.name)}"><i style="background:${t.color}"></i><b>${esc(t.name)}</b></button><div><small>${t.count}笔</small>${btn('tl-delete:'+t.name,icon('trash-2'),'删除 '+t.name,'tl-delete')}</div></section>`).join('')}</div>`:`<div class="tl-status">${icon('tags')}<h3>暂无标签</h3><p>点击右上角添加标签</p>${btn('tl-generate','生成默认标签','生成默认标签','bc-secondary')}</div>`}${['normal','empty'].includes(state.tlScenario)?btn('tl-more',`<span class="bc-menu-symbol">${icon('settings-2')}</span><span class="bc-menu-copy"><b>标签工具</b><small>新增、导入、默认生成与清理</small></span><span class="bc-menu-arrow">${icon('chevron-right')}</span>`,'标签工具','bc-menu-row tl-guide'):''}</div></div><input type="file" data-tl-file accept=".yml,.yaml" hidden aria-label="选择标签YAML">${state.tlMenu?tlMenu():''}`;}
  dTagList=tlBody;
  const tlRoutes=[['tag-management','标签管理 · 完整工具','normal'],['tag-management-empty','标签管理 · 空态','empty'],['tag-management-error','标签管理 · 重试','error'],['tag-management-loading','标签管理 · 加载','loading']];
  for(const [key,title] of tlRoutes){fDefine(key,title,'标签与分类','tag/tag_manage_page.dart',tlBody);tdPreviewGroup.appendChild(new Option(title,'flow-'+key));}
  const tlPreviousPrepare=rPrepareRoute;rPrepareRoute=function(){const route=tlRoutes.find(([key])=>state.page==='flow-'+key);if(route||state.page==='flow-tag-tools'){state.tlScenario=route?.[2]||'normal';state.tlMenu=state.page==='flow-tag-tools';state.tlMenuTop=76;state.page='leaf';state.leaf='标签管理';}tlPreviousPrepare();};
  rSpecs['tl-confirm']={title:'标签操作',host:'leaf',kind:'dialog'};rSpecs['tl-import-mode']={title:'选择导入模式',host:'leaf',kind:'dialog'};
  const tlPreviousModal=rModalBody;rModalBody=function(key){if(key==='tl-confirm'){const kind=state.tlConfirm,title=kind==='delete'?'删除标签':kind==='clear'?'清理未使用标签':'生成默认标签',message=kind==='delete'?`删除「${esc(state.tlTarget)}」后，关联交易中的该标签也会被移除，账单保留。`:kind==='clear'?`将清理 ${tlRows().filter(t=>t.count===0).length} 个未使用标签。`:'已有同名标签不会被覆盖。';rSpecs[key].title=title;return `<p>${message}</p><div class="bc-inline-actions">${btn('r-close','取消','取消标签操作','bc-secondary')}${btn('tl-confirm',kind==='generate'?'确定':'删除','确定标签操作','bc-primary '+(kind==='generate'?'':'tl-danger'))}</div>`;}if(key==='tl-import-mode')return `${menuRow('tl-mode:merge','git-merge','合并','保留现有标签，新增不存在的')}${menuRow('tl-mode:overwrite','refresh-cw','覆盖','清空未使用标签后导入')}<div class="bc-inline-actions">${btn('r-close','取消','取消标签导入','bc-secondary')}</div>`;return tlPreviousModal(key);};
  function tlDraw(){const scroll=phone.querySelector('.tl-scroll')?.scrollTop||0;render();const next=phone.querySelector('.tl-scroll');if(next)next.scrollTop=scroll;persist();}
  root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const [action,...args]=el.dataset.action.split(':'),arg=args.join(':');if(!action.startsWith('tl-'))return;event.preventDefault();event.stopImmediatePropagation();if(action==='tl-more'){const rect=el.getBoundingClientRect(),bounds=phone.getBoundingClientRect();state.tlMenuTop=Math.max(58,Math.min(rect.bottom-bounds.top+8,phone.clientHeight-212));state.tlMenu=true;tlDraw();phone.querySelector('.tl-menu-panel button')?.focus({preventScroll:true});}else if(action==='tl-close'){state.tlMenu=false;tlDraw();}else if(action==='tl-open'){state.tlMenu=false;dGo('tagDetail',{dTag:arg,tdScenario:'',tdScope:'all',tdPeriod:'all'});}else if(action==='tl-add'){state.tlMenu=false;state.teReturnTagLibrary=true;navigate('flow-tag-new');}else if(action==='tl-generate'||action==='tl-clear'||action==='tl-delete'){state.tlMenu=false;state.tlConfirm=action.slice(3);state.tlTarget=arg;tlDraw();rSpecs['tl-confirm'].title=action==='tl-delete'?'删除标签':action==='tl-clear'?'清理未使用标签':'生成默认标签';rOpenModal('tl-confirm');}else if(action==='tl-confirm'){if(state.tlConfirm==='delete')state.tlDeleted.push(state.tlTarget);else if(state.tlConfirm==='clear')state.tlDeleted.push(...tlRows().filter(t=>t.count===0).map(t=>t.name));else if(state.tlScenario==='empty')state.tlScenario='normal';rDismiss();tlDraw();notice('操作已完成（设计示例）','success');}else if(action==='tl-import'){state.tlMenu=false;tlDraw();phone.querySelector('[data-tl-file]').click();}else if(action==='tl-mode'){if(arg==='overwrite')state.tlDeleted.push(...tlRows().filter(t=>t.count===0).map(t=>t.name));for(const tag of state.tlImportTags)if(!tlRows().some(t=>t.name.toLowerCase()===tag.name.toLowerCase()))state.tlCustom.push(tag);state.tlScenario='normal';rDismiss();tlDraw();notice('标签导入完成（设计示例）','success');}else if(action==='tl-share'){const body='tags:\n  items:\n'+tlRows().map(t=>'    - name: '+JSON.stringify(t.name)+'\n      color: '+JSON.stringify(t.color)).join('\n'),url=URL.createObjectURL(new Blob([body],{type:'text/yaml'})),link=document.createElement('a');link.href=url;link.download='beecount_tags.yml';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('已导出标签YAML','success');}else if(action==='tl-retry'){state.tlScenario='normal';tlDraw();}},true);
  root.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.tlMenu){event.preventDefault();state.tlMenu=false;tlDraw();}});
  root.addEventListener('change',async event=>{if(!event.target.matches('[data-tl-file]'))return;const file=event.target.files[0];if(!file)return;if(!/\.ya?ml$/i.test(file.name)){notice('请选择 YAML 配置文件','error');return;}const lines=(await file.text()).split(/\r?\n/),start=lines.findIndex(l=>/^tags:\s*$/.test(l));if(start<0){notice('文件中没有标签数据','error');return;}let end=lines.length;for(let i=start+1;i<lines.length;i++)if(/^[^\s#]/.test(lines[i])){end=i;break;}state.tlImportTags=[];for(const line of lines.slice(start,end)){const name=line.match(/^\s*-\s*name:\s*["']?([^\n"']+)/),color=line.match(/^\s+color:\s*["']?(#[0-9a-f]{6})/i);if(name)state.tlImportTags.push({name:name[1].trim(),color:'#219c9c'});else if(color&&state.tlImportTags.length)state.tlImportTags.at(-1).color=color[1];}if(!state.tlImportTags.length){notice('文件中没有标签数据','error');return;}rOpenModal('tl-import-mode');});
  function tlSaveDraft(name,color){state.tlCustom.push({name,color});state.teReturnTagLibrary=false;state.tlScenario='normal';navigate('leaf','标签管理');notice('标签已保存（设计示例）','success');}
